-- 1. 重建主表（基础结构 + 业务列 + approval_status(用户 11:15 手动加的旧版枚举)）
CREATE TABLE IF NOT EXISTS `oa_cgsq` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `created_at` datetime(3) DEFAULT NULL COMMENT '创建时间',
  `updated_at` datetime(3) DEFAULT NULL COMMENT '更新时间',
  `created_by` bigint unsigned DEFAULT NULL COMMENT '创建人',
  `updated_by` bigint unsigned DEFAULT NULL COMMENT '更新人',
  `deleted_at` datetime(3) DEFAULT NULL COMMENT '删除时间',
  `optname` varchar(255) NOT NULL COMMENT '申请人',
  `applydt` date NOT NULL COMMENT '申请日期',
  `summarys` varchar(255) NOT NULL COMMENT '摘要',
  `reason` varchar(255) NOT NULL COMMENT '申请原因',
  `file_content` varchar(255) DEFAULT NULL COMMENT '附件',
  `approval_status` tinyint(4) NOT NULL DEFAULT 1 COMMENT '审核状态 1待审核 2审核中 3已通过 4不通过 5已驳回 6已作废 7已删除',
  PRIMARY KEY (`id`),
  KEY `idx_deleted_at` (`deleted_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购申请单';

